head.script:
scwin.screenId = "jldfil35715";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "if_kk_3_txt", fn: function(){ return ($c.data.readValue("dma_pageContext", "kk", { ctx: true, label: "param.kk" }) === 3); } }, { id: "if_kk_4_txt", fn: function(){ return ($c.data.readValue("dma_pageContext", "kk", { ctx: true, label: "param.kk" }) === 4); } }];
    $c.util.evalConds(binds);
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35715.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_self_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_self_onclick = function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; $c.win.closePopup() 
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil35715.btn_self_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////
